package crypt

// SEED SS 표(SEED-128·SEED-256 공용). 출처: 서버 snBv6Srv/go/crypt2/seed256_tables.go 사본(그대로).

import (
	"encoding/binary"
	"encoding/hex"
	"fmt"
)

const seedSS0Hex = ""
const seedSS1Hex = ""
const seedSS2Hex = ""
const seedSS3Hex = ""

func decodeSeedTable(hexStr string) ([]uint32, error) {
	raw, err := hex.DecodeString(hexStr)
	if err != nil {
		return nil, err
	}
	if len(raw) != 256*4 {
		return nil, fmt.Errorf("seed: invalid table byte length: %d", len(raw))
	}
	out := make([]uint32, 256)
	for i := 0; i < 256; i++ {
		out[i] = binary.BigEndian.Uint32(raw[i*4 : i*4+4])
	}
	return out, nil
}

func loadPackedSeedTables() ([]uint32, []uint32, []uint32, []uint32, error) {
	ss0, err := decodeSeedTable(seedSS0Hex)
	if err != nil {
		return nil, nil, nil, nil, fmt.Errorf("seed: decode SS0 failed: %w", err)
	}
	ss1, err := decodeSeedTable(seedSS1Hex)
	if err != nil {
		return nil, nil, nil, nil, fmt.Errorf("seed: decode SS1 failed: %w", err)
	}
	ss2, err := decodeSeedTable(seedSS2Hex)
	if err != nil {
		return nil, nil, nil, nil, fmt.Errorf("seed: decode SS2 failed: %w", err)
	}
	ss3, err := decodeSeedTable(seedSS3Hex)
	if err != nil {
		return nil, nil, nil, nil, fmt.Errorf("seed: decode SS3 failed: %w", err)
	}
	return ss0, ss1, ss2, ss3, nil
}
